  .title { font-size: 30px; font-weight: 780; letter-spacing: -0.02em; fill: var(--ink); }
  .subtitle { font-size: 14px; fill: var(--muted); }
  .axis-label { font-size: 12px; font-weight: 750; fill: var(--axis); }
  .axis-unit { font-size: 10px; fill: var(--muted); }
  .tick { font-size: 10px; fill: #697386; }
  .axis-line { stroke: #7c8798; stroke-width: 1.3; }
  .grid-line { stroke: var(--grid); stroke-width: 0.75; stroke-dasharray: 2 4; }
  .family-line { fill: none; stroke-linejoin: round; stroke-linecap: round; mix-blend-mode: multiply; }
  .top-line { filter: drop-shadow(0 2px 2px rgba(17, 24, 39, .18)); }
  .model-label { font-size: 10.5px; fill: #263244; paint-order: stroke; stroke: var(--bg); stroke-width: 3px; stroke-linejoin: round; }
  .model-label.top { font-size: 11.5px; font-weight: 800; }
  .legend-title { font-size: 11px; font-weight: 800; fill: var(--axis); }
  .legend-text { font-size: 11px; fill: #334155; }
  .note-title { font-size: 12px; font-weight: 800; fill: #243044; }
  .note { font-size: 11px; fill: #465569; }
  .annotation { font-size: 11px; font-weight: 700; fill: #334155; }
  .annotation-small { font-size: 10px; fill: #64748b; }
  .highlight-zone { fill: #fef3c7; opacity: 0.55; stroke: #d69e2e; stroke-width: 1; stroke-dasharray: 5 4; }
  .math-mm-zone { fill: #e0f2fe; opacity: 0.5; stroke: #0284c7; stroke-width: 1; stroke-dasharray: 5 4; }
</style>
</head>
<body>
<svg id="viz" width="1600" height="1000" viewBox="0 0 1600 1000" role="img" aria-label="Parallel coordinates chart of AI model benchmark scores"></svg>
<script>
const source = {
  unit: "normalized score (0–100)",
  data: [
    {model:"GPT-4o", family:"GPT", "Reasoning":92, "Code Generation":89, "Math / Quantitative":85, "Language Understanding":91, "Multimodal Understanding":88, "Instruction Following":90, "Inference Speed":42, "Knowledge Recall":93},
    {model:"GPT-4o-mini", family:"GPT", "Reasoning":74, "Code Generation":76, "Math / Quantitative":68, "Language Understanding":80, "Multimodal Understanding":72, "Instruction Following":82, "Inference Speed":78, "Knowledge Recall":79},
    {model:"Claude 3.5 Sonnet", family:"Claude", "Reasoning":94, "Code Generation":93, "Math / Quantitative":82, "Language Understanding":93, "Multimodal Understanding":85, "Instruction Following":95, "Inference Speed":38, "Knowledge Recall":90},
    {model:"Claude 3 Haiku", family:"Claude", "Reasoning":68, "Code Generation":70, "Math / Quantitative":60, "Language Understanding":76, "Multimodal Understanding":65, "Instruction Following":78, "Inference Speed":91, "Knowledge Recall":72},
    {model:"Gemini 1.5 Pro", family:"Gemini", "Reasoning":88, "Code Generation":82, "Math / Quantitative":72, "Language Understanding":87, "Multimodal Understanding":95, "Instruction Following":86, "Inference Speed":45, "Knowledge Recall":91},
    {model:"Gemini 1.5 Flash", family:"Gemini", "Reasoning":70, "Code Generation":68, "Math / Quantitative":58, "Language Understanding":75, "Multimodal Understanding":82, "Instruction Following":74, "Inference Speed":88, "Knowledge Recall":74},
    {model:"LLaMA 3.1 405B", family:"LLaMA", "Reasoning":86, "Code Generation":84, "Math / Quantitative":90, "Language Understanding":84, "Multimodal Understanding":45, "Instruction Following":80, "Inference Speed":35, "Knowledge Recall":88},
    {model:"LLaMA 3.1 70B", family:"LLaMA", "Reasoning":76, "Code Generation":74, "Math / Quantitative":78, "Language Understanding":75, "Multimodal Understanding":40, "Instruction Following":72, "Inference Speed":62, "Knowledge Recall":76},
    {model:"Qwen2.5 72B", family:"Qwen", "Reasoning":83, "Code Generation":86, "Math / Quantitative":92, "Language Understanding":82, "Multimodal Understanding":52, "Instruction Following":81, "Inference Speed":48, "Knowledge Recall":85},
    {model:"Qwen2.5 7B", family:"Qwen", "Reasoning":58, "Code Generation":62, "Math / Quantitative":70, "Language Understanding":64, "Multimodal Understanding":38, "Instruction Following":60, "Inference Speed":93, "Knowledge Recall":60}
  ]
};
const dims = [
  "Reasoning",
  "Inference Speed",
  "Code Generation",
  "Language Understanding",
  "Instruction Following",
  "Knowledge Recall",
  "Multimodal Understanding",
  "Math / Quantitative"
];
const labels = {
  "Reasoning": ["Reasoning"],
  "Inference Speed": ["Inference", "Speed"],
  "Code Generation": ["Code", "Generation"],
  "Language Understanding": ["Language", "Understanding"],
  "Instruction Following": ["Instruction", "Following"],
  "Knowledge Recall": ["Knowledge", "Recall"],
  "Multimodal Understanding": ["Multimodal", "Understanding"],
  "Math / Quantitative": ["Math /", "Quantitative"]
};
const colors = { GPT:"#2563eb", Claude:"#7c3aed", Gemini:"#16a34a", LLaMA:"#f97316", Qwen:"#dc2626" };
const topModels = new Set(["Claude 3.5 Sonnet", "GPT-4o", "Gemini 1.5 Pro", "Qwen2.5 72B", "LLaMA 3.1 405B"]);
const svg = document.getElementById('viz');
const W = 1600, H = 1000;
const margin = {left: 110, right: 235, top: 165, bottom: 120};
const innerW = W - margin.left - margin.right;
const innerH = H - margin.top - margin.bottom;
const x = (i) => margin.left + i * (innerW / (dims.length - 1));
const y = (v) => margin.top + (100 - v) / 100 * innerH;
function el(name, attrs={}, parent=svg) {
  const node = document.createElementNS('http://www.w3.org/2000/svg', name);
  for (const [k,v] of Object.entries(attrs)) node.setAttribute(k, v);
  parent.appendChild(node);
  return node;
}
function text(str, attrs={}, parent=svg) { const n = el('text', attrs, parent); n.textContent = str; return n; }
function pathFor(row) { return dims.map((d,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(row[d]).toFixed(1)}`).join(' '); }

el('rect', {x:0, y:0, width:W, height:H, fill:'#f8fafc'});
el('rect', {x:54, y:100, width:1492, height:810, rx:18, fill:'#ffffff', stroke:'#d7dee9'});
text('AI model capability profiles reveal clear capability–efficiency tradeoffs', {x:70, y:58, class:'title'});
text('Parallel coordinates across 8 benchmark dimensions; each line is one model, colored by family. Scores are normalized 0–100.', {x:72, y:84, class:'subtitle'});

// highlighted relationship zones
el('rect', {x:x(0)-18, y:margin.top-18, width:(x(1)-x(0))+36, height:innerH+36, rx:10, class:'highlight-zone'});
el('rect', {x:x(6)-18, y:margin.top-18, width:(x(7)-x(6))+36, height:innerH+36, rx:10, class:'math-mm-zone'});

// horizontal grid lines
[0,20,40,60,80,100].forEach(v => {
  el('line', {x1:margin.left-20, x2:margin.left+innerW+20, y1:y(v), y2:y(v), class:'grid-line'});
  text(v, {x:margin.left-35, y:y(v)+4, 'text-anchor':'end', class:'tick'});
});
text('Score', {x:margin.left-54, y:margin.top-36, class:'axis-label', 'text-anchor':'middle', transform:`rotate(-90 ${margin.left-54} ${margin.top-36})`});
text('(0–100)', {x:margin.left-54, y:margin.top+20, class:'axis-unit', 'text-anchor':'middle', transform:`rotate(-90 ${margin.left-54} ${margin.top+20})`});

// axes
const axisG = el('g');
dims.forEach((d,i) => {
  el('line', {x1:x(i), x2:x(i), y1:margin.top, y2:margin.top+innerH, class:'axis-line'}, axisG);
  [0,20,40,60,80,100].forEach(v => el('line', {x1:x(i)-5, x2:x(i)+5, y1:y(v), y2:y(v), stroke:'#7c8798', 'stroke-width':'1'}, axisG));
  const lx = x(i);
  const lines = labels[d];
  lines.forEach((line,j)=> text(line, {x:lx, y:margin.top+innerH+36+j*14, 'text-anchor':'middle', class:'axis-label'}, axisG));
  text('normalized score', {x:lx, y:margin.top+innerH+76, 'text-anchor':'middle', class:'axis-unit'}, axisG);
});

// less dominant lines first
source.data.filter(r=>!topModels.has(r.model)).forEach(row => {
  el('path', {d:pathFor(row), stroke:colors[row.family], 'stroke-width':3.0, opacity:0.62, class:'family-line'});
});
source.data.filter(r=>topModels.has(r.model)).forEach(row => {
  el('path', {d:pathFor(row), stroke:colors[row.family], 'stroke-width':5.2, opacity:0.95, class:'family-line top-line'});
});

// markers and labels
source.data.forEach(row => {
  dims.forEach((d,i) => el('circle', {cx:x(i), cy:y(row[d]), r:topModels.has(row.model)?4.2:3, fill:colors[row.family], stroke:'#fff', 'stroke-width':1.1, opacity:topModels.has(row.model)?1:.88}));
});
source.data.slice().sort((a,b)=>a["Math / Quantitative"]-b["Math / Quantitative"]).forEach((row, idx) => {
  const yy = y(row["Math / Quantitative"]);
  const offsetMap = {"Qwen2.5 72B":-8,"LLaMA 3.1 405B":5,"GPT-4o":-1,"Claude 3.5 Sonnet":2,"Gemini 1.5 Pro":7,"GPT-4o-mini":-5,"Qwen2.5 7B":8};
  text(row.model, {x:x(7)+18, y:yy+(offsetMap[row.model]||0)+4, class:`model-label ${topModels.has(row.model)?'top':''}`});
});

// annotations
text('Reasoning vs. speed tradeoff', {x:x(0)+8, y:128, class:'annotation'});
text('Flagship models rise on reasoning then dip on speed; smaller variants reverse.', {x:x(0)+8, y:145, class:'annotation-small'});
el('path', {d:`M${x(0)+30},${y(92)-10} C${x(0)+70},${y(84)} ${x(1)-80},${y(48)} ${x(1)-20},${y(42)}`, fill:'none', stroke:'#a16207', 'stroke-width':2.2, 'stroke-dasharray':'4 4'});
text('Multimodal–math divergence', {x:x(6)-10, y:128, class:'annotation', 'text-anchor':'start'});
text('Gemini peaks on multimodal; Qwen/LLaMA lead math but fall on multimodal.', {x:x(6)-10, y:145, class:'annotation-small'});
el('path', {d:`M${x(6)+20},${y(95)-8} C${x(6)+70},${y(88)} ${x(7)-75},${y(74)} ${x(7)-24},${y(72)}`, fill:'none', stroke:'#0369a1', 'stroke-width':2.2, 'stroke-dasharray':'4 4'});

// legend
const legX = 1210, legY = 122;
el('rect', {x:legX-18, y:legY-26, width:300, height:151, rx:12, fill:'#f8fafc', stroke:'#d7dee9'});
text('Model family', {x:legX, y:legY, class:'legend-title'});
Object.keys(colors).forEach((fam,i) => {
  const yy = legY + 25 + i*22;
  el('line', {x1:legX, x2:legX+38, y1:yy, y2:yy, stroke:colors[fam], 'stroke-width':4.5, 'stroke-linecap':'round'});
  text(fam, {x:legX+50, y:yy+4, class:'legend-text'});
});
el('line', {x1:legX+142, x2:legX+186, y1:legY+25, y2:legY+25, stroke:'#111827', 'stroke-width':5.2, 'stroke-linecap':'round', opacity:.75});
text('thicker = top capability profile', {x:legX+195, y:legY+29, class:'legend-text'});

// footnote / methods
const noteY = 930;
text('Reading guide', {x:70, y:noteY, class:'note-title'});
text('Higher positions indicate higher normalized benchmark scores. Axis order places key comparisons adjacent: Reasoning↔Inference Speed and Multimodal↔Math.', {x:170, y:noteY, class:'note'});
text('Source: model_benchmarks in source_data.json; scores are synthetic normalized composites documented in source_brief.md.', {x:70, y:noteY+24, class:'note'});
